         int RLE_cmd = stbi__get8(s);
         RLE_count = 1 + (RLE_cmd & 127);
         RLE_repeating = RLE_cmd >> 7;
         read_next_pixel = 1;
      } else if ( !RLE_repeating )
      {
         read_next_pixel = 1;
      }
   } else
   {
      read_next_pixel = 1;
   }
   ...
}
```

